s = input().strip()
stack = []
ok = True
for c in s:
    if c == "(" or c == "[" or c == "{":
        stack.append(c)
    else:
        if len(stack) == 0:
            ok = False
            break
        top = stack.pop()
        if c == ")" and top != "(":
            ok = False
            break
        if c == "]" and top != "[":
            ok = False
            break
        if c == "}" and top != "{":
            ok = False
            break
if len(stack) != 0:
    ok = False
print("YES" if ok else "NO")

